	//{{{ showWaitCursor() method
	/**
	 * Shows the wait cursor and glass pane.
	 */
	public synchronized void showWaitCursor()
	{
		if(waitCount++ == 0)
		{
			Cursor cursor = Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR);
			setCursor(cursor);
			applyCursorToEditPanes(cursor);
		}
	} //}}}

	//{{{ hideWaitCursor() method
	/**
	 * Hides the wait cursor and glass pane.
	 */
	public synchronized void hideWaitCursor()
	{
		if(waitCount > 0)
			waitCount--;

		if(waitCount == 0)
		{
			// still needed even though glass pane
			// has a wait cursor
			Cursor cursor = Cursor.getPredefinedCursor(Cursor.DEFAULT_CURSOR);
			setCursor(cursor);
			cursor = Cursor.getPredefinedCursor(Cursor.TEXT_CURSOR);
			applyCursorToEditPanes(cursor);
		}
	} //}}}

	//{{{ applyCursorToEditPanes() method
	/**
	 * Applies the given cursor to all edit panes in this view.
	 * @param cursor The cursor to apply
	 */
	private void applyCursorToEditPanes(Cursor cursor)
	{
		EditPane[] editPanes = getEditPanes();
		for(int i = 0; i < editPanes.length; i++)
		{
			EditPane editPane = editPanes[i];
			editPane.getTextArea().getPainter()
				.setCursor(cursor);
		}
	} //}}}

