	//{{{ processKeyEvent() method
	/**
	 * Forwards key events directly to the input handler.
	 * This is slightly faster than using a KeyListener
	 * because some Swing overhead is avoided.
	 */
	public void processKeyEvent(KeyEvent evt)
	{
		if(isClosed())
			return;

		if(getFocusOwner() instanceof JComponent)
		{
			JComponent comp = (JComponent)getFocusOwner();
			InputMap map = comp.getInputMap();
			ActionMap am = comp.getActionMap();

			if(map != null && am != null && comp.isEnabled())
			{
				Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
				if(binding != null && am.get(binding) != null)
				{
					return;
				}
			}
		}

		if(getFocusOwner() instanceof JTextComponent)
		{
			// fix for the bug where key events in JTextComponents
			// inside views are also handled by the input handler
			if(evt.getID() == KeyEvent.KEY_PRESSED)
			{
				if(isSpecialKey(evt.getKeyCode()))
					return;
			}

			Keymap keymap = ((JTextComponent)getFocusOwner())
				.getKeymap();
			if(keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null)
				return;
		}

		if(evt.isConsumed())
			return;

		evt = KeyEventWorkaround.processKeyEvent(evt);
		if(evt == null)
			return;

		handleKeyEvent(evt);

		if(!evt.isConsumed())
			super.processKeyEvent(evt);
	} //}}}

	//{{{ isSpecialKey() method
	/**
	 * Checks if the key code is one that should be handled by the text area.
	 * @param keyCode The key code to check
	 * @return true if the key is special
	 */
	private boolean isSpecialKey(int keyCode)
	{
		return keyCode == KeyEvent.VK_BACK_SPACE
			|| keyCode == KeyEvent.VK_TAB
			|| keyCode == KeyEvent.VK_ENTER;
	} //}}}

	//{{{ handleKeyEvent() method
	/**
	 * Handles the key event by dispatching to the appropriate listener.
	 * @param evt The key event
	 */
	private void handleKeyEvent(KeyEvent evt)
	{
		switch(evt.getID())
		{
		case KeyEvent.KEY_TYPED:
			handleKeyEventTyped(evt);
			break;
		case KeyEvent.KEY_PRESSED:
			handleKeyEventPressed(evt);
			break;
		case KeyEvent.KEY_RELEASED:
			handleKeyEventReleased(evt);
			break;
		}
	} //}}}

	//{{{ handleKeyEventTyped() method
	/**
	 * Handles key typed events.
	 * @param evt The key event
	 */
	private void handleKeyEventTyped(KeyEvent evt)
	{
		if(keyEventInterceptor != null)
			/* keyEventInterceptor.keyTyped(evt) */;
		else if(inputHandler.isPrefixActive()
			&& !getTextArea().hasFocus())
			inputHandler.keyTyped(evt);
	} //}}}

	//{{{ handleKeyEventPressed() method
	/**
	 * Handles key pressed events.
	 * @param evt The key event
	 */
	private void handleKeyEventPressed(KeyEvent evt)
	{
		if(keyEventInterceptor != null)
			keyEventInterceptor.keyPressed(evt);
		else
			inputHandler.keyPressed(evt);
	} //}}}

	//{{{ handleKeyEventReleased() method
	/**
